import{_ as d,o as t,c as o,a2 as a}from"./chunks/framework.mRCPFc5l.js";const p=JSON.parse('{"title":"基岩版玩家","description":"","frontmatter":{},"headers":[],"relativePath":"bedrock.md","filePath":"bedrock.md"}'),c={name:"bedrock.md"};function r(i,e,l,n,h,s){return t(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="基岩版玩家" tabindex="-1">基岩版玩家 <a class="header-anchor" href="#基岩版玩家" aria-label="Permalink to &quot;基岩版玩家&quot;">​</a></h1><p>基岩版玩家（手机/主机版）在服务器中同样可以方便地使用各项功能，还额外拥有**表单（GUI 菜单）**支持，操作更直观。</p><h2 id="表单指令" tabindex="-1">表单指令 <a class="header-anchor" href="#表单指令" aria-label="Permalink to &quot;表单指令&quot;">​</a></h2><table tabindex="0"><thead><tr><th>指令</th><th>表单内容</th></tr></thead><tbody><tr><td><code>/tpgui</code></td><td>传送表单（请求传送到其他玩家）</td></tr><tr><td><code>/msggui</code></td><td>消息表单（给玩家发私聊）</td></tr><tr><td><code>/homegui</code></td><td>家表单（管理你的家）</td></tr><tr><td><code>/phomegui</code></td><td>公开家表单</td></tr><tr><td><code>/warpgui</code></td><td>传送点表单</td></tr><tr><td><code>/paygui</code></td><td>转账表单（给玩家转钻石）</td></tr></tbody></table><p>在表单界面点选即可完成操作，无需记忆复杂指令。</p><h2 id="自动表单" tabindex="-1">自动表单 <a class="header-anchor" href="#自动表单" aria-label="Permalink to &quot;自动表单&quot;">​</a></h2><ul><li><strong>死亡返回</strong>：基岩版玩家死亡复活后，会自动弹出「返回死亡点」表单，可选择是否回到死亡地点。</li><li><strong>传送请求</strong>：收到其他玩家的传送请求时，会自动弹出接受/拒绝表单。</li></ul><h2 id="名字前缀" tabindex="-1">名字前缀 <a class="header-anchor" href="#名字前缀" aria-label="Permalink to &quot;名字前缀&quot;">​</a></h2><ul><li>基岩版玩家进入服务器后，名字前会带有一个 <strong><code>.</code></strong> 前缀，用于与 Java 版玩家区分。</li><li>例如基岩玩家「小明」在服务器里显示为 <code>.小明</code>。</li></ul><h2 id="通用功能" tabindex="-1">通用功能 <a class="header-anchor" href="#通用功能" aria-label="Permalink to &quot;通用功能&quot;">​</a></h2><p>基岩版玩家同样可以使用所有基础指令：</p><ul><li>传送：<code>/spawn</code>、<code>/sethome</code>、<code>/home</code>、<code>/tpa</code>、<code>/warp</code></li><li>聊天：<code>/msg</code>、<code>!all</code></li><li>经济：<code>/money</code>、<code>/pay</code>、<code>/diamond</code></li><li>联盟与领地：<code>/union</code>、<code>/pclaim</code>、<code>/gclaim</code></li><li>前缀：<code>/prefix</code></li><li>QQ 绑定：<code>/qqbind</code></li></ul><h2 id="小提示" tabindex="-1">小提示 <a class="header-anchor" href="#小提示" aria-label="Permalink to &quot;小提示&quot;">​</a></h2><ul><li>使用表单是最省事的方式，基岩版玩家推荐优先使用 <code>/xxxgui</code> 系列。</li><li>如果想用传统指令，输入时注意基岩版自动补全会辅助你。</li></ul>',14)])])}const m=d(c,[["render",r]]);export{p as __pageData,m as default};
